message.content:
{
  "description": "The creature is shown in right-facing side profile on a plain light background as a single quadrupedal animal that combines mammalian and insect features. It has the overall body shape, dense brown fur, head shape, and clawed paws of a brown bear, but most of its back, neck, sides, and outer limbs are covered by a highly glossy, dark brown to black segmented exoskeleton resembling a beetle. The armor forms overlapping plates along the dorsal midline from neck to tail, with large smooth shoulder and hip shields and smaller plates wrapping the upper and lower legs, while the underside and lower flanks show lighter tan segmented plates with a row of oval openings. Two large, curved, black, serrated horns rise from the top of the head, and a short, pointed, segmented tail extends from the rear. Brown fur remains visible on the head, neck, throat, lower legs, and paws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head covered in dense brown fur with a lighter tan muzzle, a large black nose at the tip, small dark brown eyes, and fine whiskers on the muzzle",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "two large glossy black horns with jagged tooth-like projections along the inner edges; the upper horn is longer and arches strongly forward and upward, the lower horn is shorter and curves upward from the forehead, both emerging from a shiny dark base",
      "where": "on top of the head between and just in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "small rounded ears covered in short brown fur",
      "where": "on the top sides of the head, partially tucked under the base of the horns and the neck plates"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs with brown fur, each with large glossy dark plates covering the thigh and shin, leaving fur exposed at the joints",
      "where": "under the body, two forelegs toward the front right and two hind legs toward the rear left"
    },
    {
      "part": "feet",
      "looks_like": "broad furry paws with five long dark claws on each foot, the fur is brown and the claws are curved and pointed",
      "where": "at the bottom ends of the four legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "short tapered tail made of overlapping glossy dark segments ending in a pointed tip, curving slightly downward",
      "where": "at the far left rear of the body extending from the end of the dorsal plates"
    },
    {
      "part": "plates",
      "looks_like": "overlapping highly reflective dark brown-black plates with tan seams covering the back, neck, shoulders and hips, plus smaller dark plates on the outer legs; the lower sides and belly have lighter tan segmented plates with a row of seven oval holes along the mid-flank",
      "where": "covering the dorsal back from neck to tail, the sides of the neck and torso, the shoulder and hip regions, and wrapping parts of all four legs"
    },
    {
      "part": "shell",
      "looks_like": "a continuous domed glossy carapace formed by the fused dorsal plates, smooth and reflective with distinct segment lines",
      "where": "over the back and shoulders, forming the main upper armor from behind the neck to the base of the tail"
    }
  ],
  "attached_objects": [
    "a small glossy black beetle body with two large curved serrated horns, its head with visible eyes and small jointed legs and antennae gripping the fur on top of the bear-like head"
  ],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 2,
  "heads": 2,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 6,
  "tails": 1
}
